package com.xjtu.iron.idempotent.api.repository;public final class IdempotencyWriteResult{private final IdempotencyWriteStatus status;private final IdempotencyRecord record;private final Throwable error;private IdempotencyWriteResult(IdempotencyWriteStatus s,IdempotencyRecord r,Throwable e){status=s;record=r;error=e;}public static IdempotencyWriteResult of(IdempotencyWriteStatus s,IdempotencyRecord r){return new IdempotencyWriteResult(s,r,null);}public static IdempotencyWriteResult providerError(Throwable e){return new IdempotencyWriteResult(IdempotencyWriteStatus.PROVIDER_ERROR,null,e);}public IdempotencyWriteStatus getStatus(){return status;}public IdempotencyRecord getRecord(){return record;}public Throwable getError(){return error;}}
